import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";import"./chunks/assets.B-QExMyb.js";var i=JSON.parse(`{"title":"设计目标","description":"","frontmatter":{},"headers":[],"relativePath":"development/intro/design.md","filePath":"development/intro/design.md","lastUpdated":1618115805000}`),a={name:`development/intro/design.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /development/intro/design.md for this page in Markdown format</div><h1 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to “设计目标”">​</a></h1><ul><li>Xray 内核提供了一个平台，支持必要的网络代理功能，在其之上可以进二次开发，以提供更好的用户体验；</li><li>以跨平台为首要原则，以减少二次开发的成本；</li></ul><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to “架构”">​</a></h2><p><img src="/assets/framework.Bf6xCZ4u.png" alt="Architecture" width="1206" height="922"></p><p>内核分为三层：应用层、代理层和传输层。</p><p>每一层内包含数个模块，模块间互相独立，同类型的模块可无缝替换。</p><h3 id="应用层" tabindex="-1">应用层 <a class="header-anchor" href="#应用层" aria-label="Permalink to “应用层”">​</a></h3><p>应用层包含一些代理层中常用的功能，这些功能被抽象出来，以便在不同的代理模块中复用。</p><p>应用层的模块应为纯软件实现，与硬件或平台相关的技术无关。</p><p>重要模块列表：</p><ul><li>Dispatcher: 用于把入站代理所接收到的数据，传送给出站代理；</li><li>Router: 路由模块，详见 <a href="./../../config/routing.html">路由配置</a>；</li><li>DNS: 内置的 DNS 服务器模块；</li><li>Proxy Manager: 代理管理器；</li></ul><h3 id="代理层" tabindex="-1">代理层 <a class="header-anchor" href="#代理层" aria-label="Permalink to “代理层”">​</a></h3><p>代理层分为两部分：入站代理（Inbound Proxy）和出站代理（Outbound Proxy）。</p><p>两部分相互独立，入站代理不依赖于某个特定的出站代理，反之亦然。</p><h4 id="入站代理" tabindex="-1">入站代理 <a class="header-anchor" href="#入站代理" aria-label="Permalink to “入站代理”">​</a></h4><ul><li>实现 <a href="https://github.com/xtls/Xray-core/blob/main/proxy/proxy.go" target="_blank" rel="noreferrer">proxy.Inbound</a> 接口；</li></ul><h4 id="出站代理" tabindex="-1">出站代理 <a class="header-anchor" href="#出站代理" aria-label="Permalink to “出站代理”">​</a></h4><ul><li>实现 <a href="https://github.com/xtls/Xray-core/blob/main/proxy/proxy.go" target="_blank" rel="noreferrer">proxy.Outbound</a> 接口；</li></ul><h3 id="传输层" tabindex="-1">传输层 <a class="header-anchor" href="#传输层" aria-label="Permalink to “传输层”">​</a></h3><p>传输层提供一些网络数据传输相关的工具模块。</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};